  exec('whoami', (err, stdout, stderr) => {
    if (err) {
      console.error(`Error: ${stderr}`);
      return;
    }
    console.log(stdout);
  });
} else {
  exec('whoami', (err, stdout, stderr) => {
    if (err) {
      console.error(`Error: ${stderr}`);
      return;
    }
    console.log(stdout);
  });
}
```

This script checks the operating system platform and runs the appropriate command (`whoami`) accordingly. If you want to use Node.js to spawn a process directly without using `exec`, you can do something like this:

```javascript
const { spawn } = require('child_process');

const child = spawn('whoami', { shell: true });

child.stdout.on('data', (data) => {
  console.log(`stdout: ${data}`);
});

child.stderr.on('data', (data) => {
  console.error(`stderr: ${data}`);
});

child.on('close', (code) => {
  console.log(`child process exited with code ${code}`);
});
```

This will spawn the `whoami` command and handle its output and errors appropriately.

