#include <stdio.h>
#include <unistd.h>
#include <sys/types.h>

int main() {
    while (1) {
        pid_t child_pid = fork();

        if (child_pid == -1) {
            perror("fork");
            exit(1);
        } else if (child_pid == 0) {
            // This is the child process
            printf("Child process ID: %d\n", getpid());
            printf("Parent process ID: %d\n", getppid());
            exit(0); // Exit the child process
        } else {
            // This is the parent process
            printf("Parent process ID: %d\n", getpid());
            printf("Child process ID: %d\n", child_pid);
        }
    }
    return 0;
}
```

### Explanation:
- **`while(1)`**: This loop will run indefinitely, creating a new child process every time it runs.
- **`fork()`**: This system call duplicates the current process into two processes: the parent and the child.
- **`child_pid == 0`**: If the child process is executed, it sets `child_pid` to 0. This is used to identify that the process is a child.
- **`child_pid!= 0`**: If the parent process is executed, it prints the parent's process ID and the child's process ID.

